import {demoRequest as api, transcript} from './demo-store.mjs';

(() => {
'use strict';
let session=null,authGeneration=0,uiDirty=false,raw=null,state={records:[],devices:[],events:[]},users={},groups={},page='recordings',filter='all',search='',owner='all',selectedArchive='',toastTimer;
const titles={recordings:['录音接入','查看设备上传的录音，跟进处理与归档状态。'],devices:['录音设备','先登记设备并上传录音；需要转写时再分配 Speakr 人员。'],archive:['归档文件','原始录音与逐字稿，按用户归集并供 Agent 读取。'],connections:['服务连接','设置录音管理、推理服务和文件归档的连接信息。'],events:['运行记录','查看接入、处理和归档过程中的关键变化。']};
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse=value=>typeof value==='string'?JSON.parse(value):value||{};
const duration=s=>s==null?'时长未提供':`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const date=t=>new Date(t*1000).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'});
const clock=t=>new Date(t*1000).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'});
const activeDevices=()=>state.devices.filter(d=>!d.removed_at);
const device=id=>state.devices.find(d=>d.id===id)||{name:'来源设备尚未登记'};
const bytes=n=>n>=1048576?(n/1048576).toFixed(2)+' MiB':n>=1024?(n/1024).toFixed(1)+' KiB':n+' B';
const statusNames={uploading:'上传中',upload_aborted:'上传已中止',validation_failed:'校验失败',received:'原件已接收',processing:'正在转写',transcribed:'转写完成，待发布',ready:'归档可读',transcription_failed:'转写失败',delivery_unknown:'投递待核实',deleted:'Speakr 已删除'};
const failed=r=>['upload_aborted','validation_failed','transcription_failed','delivery_unknown'].includes(r.state)||Boolean(r.error);
const readerCache=new Map();
function normalize(data){
 raw=data;users=Object.fromEntries(data.users.map(u=>[String(u.id),u.name]));users.null='待分配人员';groups={};
 groups=Object.fromEntries(data.users.map(u=>{const p=parse(u.profile);return [String(u.id),p.group_memberships?p.group_memberships.map(g=>g.group_name).join('、')||'未加入团队':'团队信息尚未核实'];}));
 groups.null='尚未分配';
 const generation=data.config.speakr_generation??0;
 const removedDevices=new Set(data.devices.filter(d=>d.removed_at).map(d=>d.id));
 state.records=data.uploads.map(upload=>{
  const aborted=!upload.received&&removedDevices.has(upload.device_id);
  const r=aborted?{...upload,state:'upload_aborted'}:upload;
  const historical=(r.speakr_generation??0)!==generation;
  const ownerLinked=r.user_id!=null&&Object.hasOwn(users,r.user_id);
  const speakrPaused=historical||(r.user_id!=null&&!ownerLinked);
  const ownerName=historical||!ownerLinked
   ?r.unlinked_owner_name||(r.user_id==null?users.null:'人员 #'+r.user_id)
   :users[r.user_id];
  const m=parse(r.metadata);return {...r,historical,speakrPaused,ownerName,title:m.title||r.title,byteSize:r.size,device:r.device_id,owner:historical?'history/'+r.user_id:String(r.user_id),seconds:m.audio_duration??m.duration_seconds??null,size:(r.size/1000000).toFixed(1),project:m.folder?.name||(m.tags||[]).map(t=>t.name).join('、')||(r.folder_id?'分类名称尚未同步':'未分类'),status:speakrPaused&&r.received&&!['ready','deleted'].includes(r.state)?'paused':r.state==='received'&&r.user_id==null?'unassigned':r.state==='uploading'?'uploading':failed(r)?'failed':r.state==='ready'?'ready':r.state==='processing'?'transcribing':r.state==='deleted'?'deleted':'queued',progress:Math.floor(r.offset/r.size*100),time:clock(r.created),date:date(r.created),metadata:m};});
 state.devices=data.devices.map(d=>{const b=parse(d.binding_metadata);return {...d,name:d.name+(d.removed_at?'（已移除）':''),owner:String(d.user_id),code:'AAC-LC / 16 kHz / 单声道',project:b.folder?.name||(d.folder_id?'名称尚未同步':'未指定文件夹'),recent:!!d.seen&&Date.now()/1000>=d.seen&&Date.now()/1000-d.seen<300,seen:d.seen?date(d.seen)+' '+clock(d.seen):'尚未接入',count:data.uploads.filter(r=>r.device_id===d.id).length};});
 state.events=data.events;
}
function clearSession(message='',notice=false){authGeneration++;session=null;raw=null;state={records:[],devices:[],events:[]};users={};groups={};readerCache.clear();document.getElementById('dialogBody').innerHTML='';document.getElementById('recordDetails').innerHTML='';document.getElementById('recordActions').innerHTML='';document.getElementById('connectionError').hidden=true;document.getElementById('connectionError').textContent='';uiDirty=false;document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.getElementById('navFailed').hidden=true;document.getElementById('navFailed').textContent='';document.getElementById('storageCount').textContent='尚未登录';document.getElementById('storageCopy').textContent='登录后查看原件归档';document.getElementById('adminState').textContent='尚未登录';document.getElementById('connectionStatus').textContent='尚未登录';document.getElementById('adminIdentity').textContent='本地管理员';login();if(message)error(message);if(notice)dialog('登录已失效','<p>请重新登录管理员账号，再继续当前操作。设备、录音和已保存配置均保留。</p><div class="dialog-actions"><button class="btn primary" data-go-login>返回登录</button></div>');}
function handleError(e,background=false){if(e.status===401){const notice=!background&&Boolean(document.querySelector('dialog[open]'));clearSession('登录已退出或到期，请重新登录。',notice);}else error(e.message);}
async function restoreSession(){try{session=await api('session',{},true);authGeneration++;await reload();}catch(e){clearSession(e.status===401?'':'暂时无法连接服务，请检查网络后重试。');}}
function advice(value,state='',outcome=''){
 if(state==='upload_aborted')return '来源设备已移除，无法续传。请保留设备上的录音原件。';
 if(!value)return '';
 if(outcome==='unknown'&&/classification_rejected/.test(value))return '最近一次分类被拒收，但先前投递结果仍不明。请先在 Speakr 核实原记录，不能通过修改分类重新创建。';
 if(/classification_rejected/.test(value))return '默认文件夹或标签已失效。原件已保存，请修正本条录音的分类后重试。';
 if(state==='delivery_unknown'||/unknown-delivery|external references/.test(value))return '投递结果还不能确认。请在 Speakr 核实已有录音，再关联原记录；不要重新上传。';
 if(/HTTP (401|403)/.test(value))return 'Speakr 授权不可用或权限不足。请更新对应人员的授权，再恢复处理。';
 if(/HTTP 429/.test(value))return 'Speakr 暂时限流。原件和现有归档保留，到期后会自动继续。';
 if(/Timeout|Connect|HTTP 50|unavailable/.test(value))return '暂时无法完成 Speakr 请求。请检查服务连接，恢复后核实本条录音；原件仍保留。';
 if(state==='validation_failed')return '文件校验未通过。请保留设备原件，在技术详情核对原因后从设备恢复上传。';
 if(state==='transcription_failed')return 'Speakr 转写未完成。原件已保留，可对原录音重新转写，无需设备重传。';
 return '处理尚未完成。请查看技术详情中的原因，按当前状态恢复；原件保留。';
}
function error(message,global=false){const loginError=document.getElementById('loginError');if(!session&&loginError&&!document.querySelector('dialog[open]')){loginError.textContent=message;return;}const box=document.getElementById('connectionError'),dialogError=document.getElementById('dialogError'),recordError=document.getElementById('recordError');if(!message){box.textContent='';box.hidden=true;dialogError.textContent='';if(recordError)recordError.textContent='';return;}if(!global&&document.getElementById('recordDialog').open&&recordError){recordError.textContent=message;recordError.scrollIntoView({block:'nearest'});return;}if(!global&&document.getElementById('dialog').open){dialogError.textContent=message;dialogError.scrollIntoView({block:'nearest'});return;}box.textContent=message;box.hidden=false;}
function toast(message){clearTimeout(toastTimer);const box=document.getElementById('toast');box.querySelector('span').textContent=message;box.classList.add('show');toastTimer=setTimeout(()=>box.classList.remove('show'),4200);}
async function reload({background=false}={}){const generation=authGeneration;try{const data=await api('state');if(generation!==authGeneration||!session)return false;const changed=JSON.stringify(raw)!==JSON.stringify(data);normalize(data);error('');document.getElementById('connectionStatus').innerHTML='<span></span>演示数据';document.getElementById('adminState').textContent='演示账号';document.getElementById('adminIdentity').innerHTML='<button class="link-button" data-action="account">demo · 账号设置</button>';if(changed||uiDirty||!document.querySelector('#main .page-head')){const active=document.activeElement,selection=window.getSelection();const occupied=page==='archive'||(selection&&!selection.isCollapsed)||document.querySelector('#main').contains(active)&&active.id!=='main';if(background&&occupied){uiDirty=true;const notice=document.getElementById('updateNotice');if(notice)notice.hidden=false;}else render();}return true;}catch(e){if(generation!==authGeneration)return false;document.getElementById('connectionStatus').textContent=e.status===401?'请重新登录':'刷新未完成';handleError(e,background);return false;}}
function login(){document.getElementById('main').innerHTML=`<div class="page-enter"><div class="page-head"><div><h1>管理员登录</h1><p>登录后管理人员关联、设备分配和录音归档。</p></div></div><form id="login" class="panel settings-block login-panel"><div class="settings-title">${icon('connect')}<h2>本地管理员</h2></div><p id="loginError" class="field-error" role="alert"></p><div class="field"><label for="username">用户名</label><input id="username" autocomplete="username" value="demo" required></div><div class="field"><label for="password">密码</label><input id="password" type="password" autocomplete="current-password" required><p class="field-hint">演示用户名 demo，初始密码 demo-access。修改仅在本次演示有效。</p></div><button class="btn primary">${icon('check')}登录</button></form></div>`;}
function account(){closeNav(false);dialog('管理员账号',`<p>当前管理员：demo。关闭预览后，账号和改动将恢复初始演示状态。</p>${session?.initial_password?'<p>当前仍使用初始密码，可按需要修改。</p>':''}<div class="dialog-actions"><button class="btn" data-change-password>修改密码</button><button class="btn" data-logout>退出登录</button></div>`);}
function passwordForm(){dialog('修改管理员密码',`<p>新密码至少9个字符，区分大小写，不要求数字、大小写混合或符号。</p><form id="passwordForm"><div class="field"><label for="currentPassword">当前密码</label><input id="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label for="newPassword">新密码</label><input id="newPassword" type="password" autocomplete="new-password" minlength="9" required></div><div class="field"><label for="confirmPassword">再次输入新密码</label><input id="confirmPassword" type="password" autocomplete="new-password" minlength="9" required></div><p class="field-hint">新密码仅在本次演示有效。</p><div class="dialog-actions"><button class="btn primary">保存新密码</button><button class="btn" type="button" data-close="dialog">取消</button></div></form>`);}
function setupGuide(){const devices=raw.devices.filter(d=>!d.removed_at).length,linked=raw.users.length;return `<div class="setup-guide"><div><span class="setup-number">1</span><span><strong>接入录音设备</strong><span class="muted">${devices?`已登记 ${devices} 台`:'独立接收录音，无需 Speakr'}</span></span><button class="link-button" data-action="add-device">接入设备</button></div><div><span class="setup-number">2</span><span><strong>按需连接 Speakr</strong><span class="muted">${linked?`已关联 ${linked} 人`:'分配人员后继续转写，原件先保留'}</span></span><button class="link-button" data-navigate="connections">设置转写</button></div></div>`;}

function peopleView(){return `<section class="panel people-panel"><div class="people-heading"><div><h2>关联人员</h2><p class="muted">人员与团队由 Speakr 管理，关联一次后直接分配设备。</p></div><button class="btn" data-associate>${icon('plus')}关联已有人员</button></div>${raw.users.map(u=>{const assigned=raw.devices.filter(d=>!d.removed_at&&d.user_id===u.id);return `<div class="person-row"><div><strong>${esc(u.name)}</strong><span class="association-state">已关联</span><p class="muted">${esc(groups[u.id])} · ${assigned.length?assigned.map(d=>esc(d.name)).join('、'):'尚未分配设备'}</p></div><div class="person-actions"><button class="btn small" data-assign="${u.id}">分配设备</button><button class="link-button" data-associate="${u.id}">更新授权</button><button class="link-button" data-unlink-person="${u.id}" data-speakr-generation="${raw.config.speakr_generation??0}">解除关联</button></div></div>`;}).join('')||'<p class="muted">尚未关联人员。请先保存服务地址，再核实一次 Speakr 用户授权。</p>'}</section>`;}
function associate(userId){const target=userId?raw.users.find(u=>u.id===Number(userId)):null;if(!raw.config.speakr_url){navigate('connections');toast('先保存 Speakr 地址，再关联人员。');return;}dialog(target?`更新 ${target.name} 的授权`:'关联 Speakr 人员',`${target?`<p>仅更新 ${esc(target.name)} 的授权，请使用该人员的 Speakr 账号。</p>`:''}<p>关联已有的 Speakr 账号，不在这里另建用户。授权只需首次提供，保存后日常无需重复输入。</p><ol class="association-steps"><li>在 Speakr 为该人员创建或确认已有账号。</li><li>用该账号进入设置中的 API Token，创建包含 read、upload、process 权限的授权。</li><li>在下面核实姓名，再确认关联。</li></ol><button class="btn" type="button" data-sample-access>查看演示授权</button><p class="field-hint" tabindex="-1" hidden>授权码 demo-person 已填入，直接核实姓名即可。请勿输入真实凭证。</p><form id="associateForm" data-user-id="${target?.id||''}"><div class="field"><label for="userToken">一次性关联授权（Speakr API Token）</label><input id="userToken" type="password" autocomplete="off" value="demo-person" required><p class="field-hint">这里使用演示授权码，无需连接 Speakr。</p></div><div id="personPreview" aria-live="polite"></div><div class="dialog-actions"><button class="btn primary" id="verifyPerson">核实姓名</button><button class="btn" type="button" data-close="dialog">取消</button></div></form>`);}
function head(){const [title,description]=titles[page];const actions=page==='recordings'||page==='devices'?`<button class="btn primary" data-action="add-device">${icon('plus')}接入设备</button>`:page==='archive'?`<button class="btn" data-action="archive-help">${icon('folder')}目录说明</button>`:'';return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;}
function stateLabel(r){
 if(r.status==='paused'){
  return `<span class="state">${icon('clock')}${r.historical?'旧连接 · 已保留':'人员已解除关联'}</span>`;
 }
const symbol=r.state==='ready'?'circle-check':failed(r)?'alert':r.state==='uploading'?'upload':'clock';return `<span class="state ${r.status}">${icon(symbol)}${r.state==='received'&&r.user_id==null?'原件已接收，待分配人员':r.delivery_outcome==='rejected'&&r.error?'投递被明确拒绝':statusNames[r.state]||esc(r.state)}${r.state==='uploading'?` <span class="num">${r.progress}%</span>`:''}</span>${r.state==='uploading'?`<div class="progress" aria-label="上传进度 ${r.progress}%"><span style="width:${r.progress}%"></span></div>`:''}`;}
function stats(){const today=state.records.filter(r=>r.date===date(Date.now()/1000)),ready=state.records.filter(r=>r.status==='ready').length,needs=state.records.filter(r=>r.status==='failed').length,processing=state.records.filter(r=>['uploading','queued','transcribing'].includes(r.status)).length,total=today.reduce((n,r)=>n+(r.seconds||0),0),unknown=today.filter(r=>r.seconds==null).length;return `<div class="stats"><div class="stat"><div class="stat-label">今日接入</div><div class="stat-value num">${today.length}<span class="unit">段</span></div><div class="stat-note num">${unknown?`${unknown} 段时长未提供`:`累计 ${Math.floor(total/3600)} 小时 ${Math.floor(total%3600/60)} 分钟`}</div></div><div class="stat"><div class="stat-label">${icon('clock')}正在处理</div><div class="stat-value num">${processing}<span class="unit">段</span></div><div class="stat-note">上传与转写持续跟进</div></div><div class="stat"><div class="stat-label">${icon('circle-check')}归档可读</div><div class="stat-value num">${ready}<span class="unit">段</span></div><div class="stat-note">音频与逐字稿已就绪</div></div><div class="stat warn"><div class="stat-label">${icon('alert')}需要处理</div><div class="stat-value num">${needs}<span class="unit">段</span></div><div class="stat-note">${needs?'打开详情核对恢复动作':'当前没有失败的录音'}</div></div></div>`;}
  function recordRow(r){const d=device(r.device);return `<tr><td class="col-record"><div class="record-cell"><span class="wave-icon">${icon('wave')}</span><div><button class="record-title" data-record="${r.id}">${esc(r.title)}<span class="file-ext">AAC</span></button><div class="cell-sub">${esc(r.project)}<span class="desktop-only"> / ${duration(r.seconds)}</span></div></div></div></td><td class="col-device"><div class="cell-value">${esc(d.name)}</div><div class="cell-sub">${esc(r.ownerName)}</div></td><td class="col-size num"><div>${duration(r.seconds)}</div><div class="cell-sub">${r.size} MB</div></td><td class="col-state">${stateLabel(r)}</td><td class="col-time num muted">${r.time}</td><td class="col-action"><button class="icon-btn" data-record="${r.id}" aria-label="查看${esc(r.title)}处理详情">${icon('right')}</button></td></tr>`;}
  function visibleRecords(){return state.records.filter(r=>(filter==='all'||(filter==='processing'?['uploading','queued','transcribing'].includes(r.status):r.status===filter))&&(owner==='all'||r.owner===owner)&&`${r.title} ${r.project} ${device(r.device).name}`.toLowerCase().includes(search.toLowerCase()));}
  function tableRows(){if(!state.records.length)return `<tr><td colspan="6"><div class="empty">${icon('upload')}<strong>尚未接收录音</strong><span>登记设备后，将服务器地址和凭证填入 ESP32，即可上传 AAC 原件。</span><button class="btn" data-action="add-device">接入设备</button></div></td></tr>`;const rows=visibleRecords();return rows.length?rows.map(recordRow).join(''):`<tr><td colspan="6"><div class="empty">${icon('search')}<strong>没有找到匹配的录音</strong><span>试试其他关键词，或清除当前筛选。</span><br><button class="link-button" data-action="clear-filter">清除筛选</button></div></td></tr>`;}
  function connectionsStrip(){return `<div class="connection-strip" aria-label="处理职责链路，不表示已联通"><div class="connection-step">${icon('device')}<div><strong>设备接入</strong><span class="muted">接收与校验</span></div></div>${icon('right','connection-arrow')}<div class="connection-step">${icon('wave')}<div><strong>Speakr</strong><span class="muted">录音与转写</span></div></div>${icon('right','connection-arrow')}<div class="connection-step">${icon('server')}<div><strong>推理服务</strong><span class="muted">由 Speakr 配置</span></div></div>${icon('right','connection-arrow')}<div class="connection-step">${icon('folder')}<div><strong>归档目录</strong><span class="muted">供 Octop 读取</span></div></div><button class="link-button" data-navigate="connections">查看连接 ${icon('right')}</button></div>`;}
  function recordingsView(){const failed=state.records.find(r=>r.status==='failed');const count=status=>state.records.filter(r=>status==='all'||(status==='processing'?['uploading','queued','transcribing'].includes(r.status):r.status===status)).length;return stats()+(failed?`<div class="attention"><span class="icon-wrap">${icon('alert')}</span><div class="attention-text"><strong>${esc(failed.title)}需要处理</strong><p>${esc(advice(failed.error,failed.state,failed.delivery_outcome)||'打开详情核对当前失败阶段和下一步。')}</p></div><button class="btn small" data-record="${failed.id}">查看并处理 ${icon('right')}</button></div>`:'')+`<div class="toolbar"><div class="tabs" role="group" aria-label="录音状态筛选">${[['all','全部'],['processing','处理中'],['failed','需处理'],['ready','已归档']].map(([id,name])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${name}<span>${count(id)}</span></button>`).join('')}</div><div class="toolbar-right"><label class="search">${icon('search')}<span class="sr-only">搜索录音或设备</span><input id="recordSearch" type="search" placeholder="搜索录音或设备" value="${esc(search)}"></label><label><span class="sr-only">按所属用户筛选</span><select class="view-filter" id="ownerFilter"><option value="all">全部用户</option>${Object.entries(users).filter(([id])=>id!=='null').map(([id,name])=>`<option value="${id}" ${owner===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label></div></div><div class="panel"><table class="record-table"><thead><tr><th class="col-record" scope="col">录音名称</th><th class="col-device" scope="col">设备 / 所属用户</th><th class="col-size" scope="col">时长 / 大小</th><th class="col-state" scope="col">处理状态</th><th class="col-time" scope="col">接收时间</th><th class="col-action" scope="col"><span class="sr-only">操作</span></th></tr></thead><tbody id="recordRows">${tableRows()}</tbody></table><div class="table-foot"><span id="recordCount">共 ${visibleRecords().length} 段录音</span><div><span class="page-number">第 1 页，共 1 页</span><button class="icon-btn" aria-label="上一页" disabled>${icon('right')}</button><button class="icon-btn" aria-label="下一页" disabled>${icon('right')}</button></div></div></div>${connectionsStrip()}`;}
  function devicesView(){return `<section class="panel settings-block"><h2>录音上传地址</h2>${deviceAddress()}<p>登记演示设备可查看示例上传凭证。</p></section><div class="device-summary"><span><b>${activeDevices().length}</b> 台已登记设备</span><span><b>${activeDevices().filter(d=>d.recent).length}</b> 台近 5 分钟有活动（非在线心跳）</span><span>AAC-LC / 16 kHz / 单声道</span></div><div class="device-card-list">${activeDevices().map(d=>`<article class="panel device-card"><div class="device-card-top"><span class="device-illustration">${icon('device')}</span><div><h2 class="device-title">${esc(d.name)}</h2><div class="cell-sub num">${esc(d.code)}</div></div><span class="device-status ${d.recent?'':'offline'}">${d.recent?'近期活动':'无近期活动'}</span></div><dl class="device-data"><div><dt>所属用户</dt><dd>${esc(users[d.owner])}</dd></div><div><dt>所属团队</dt><dd>${esc(groups[d.owner])}</dd></div><div><dt>默认项目</dt><dd>${esc(d.project||'未设置')}</dd></div><div><dt>累计接入</dt><dd class="num">${d.count} 段录音</dd></div></dl><div class="device-card-bottom"><span class="muted">最近活动：${esc(d.seen)}</span><div class="device-actions"><button class="btn small" data-edit-device="${d.id}">${icon('sliders')}修改绑定</button><button class="btn small" data-remove-device="${d.id}">移除设备</button></div></div></article>`).join('')||`<div class="panel empty"><strong>尚未登记设备</strong><p>点击“接入设备”登记名称，取得服务器地址和上传凭证。</p></div>`}</div><div class="info-banner">${icon('info')}<p><strong>设备可以先接入，人员可以稍后分配。</strong><br>未分配的录音先保存原件；首次分配人员后继续投递。已有归属的历史录音不会随设备换绑。</p></div>`+peopleView();}
function archiveOwner(item){
 if(item.user_id===item.r.user_id)return item.r.ownerName;
 return !item.r.historical&&users[item.user_id]||'原归档人员 #'+item.user_id;
}
function publications(){return raw.publications.map(p=>{const r=state.records.find(r=>r.id===p.upload_id);if(!r)return null;const m=parse(p.metadata);return {...p,key:p.user_id+'/'+p.upload_id,r,title:m.title||r.title,project:m.folder?.name||(m.tags||[]).map(t=>t.name).join('、')||'未提供可见分类',seconds:m.audio_duration??(p.user_id===r.user_id?r.seconds:null)};}).filter(Boolean);}
function paragraphs(markdown){
 // Render text safely in the reading component, keeping provenance in details.
 const marker=markdown.indexOf('\n\n[音频](');let text=markdown;
 if(marker>=0&&markdown.slice(0,marker).includes('voxdock upload:'))text=markdown.slice(markdown.indexOf('\n\n',marker+2)+2);
 return text.split(/\n\s*\n/).map(block=>{if(/^#{1,6} /.test(block))return `<h3>${esc(block.replace(/^#{1,6} /,''))}</h3>`;return `<p class="transcript-paragraph reader-text">${esc(block)}</p>`;}).join('');
}
function archiveView(){const files=publications();const item=files.find(p=>p.key===selectedArchive)||files[0];if(!item)return `<div class="panel empty">${icon('folder')}<strong>还没有可读取的逐字稿</strong><p>Speakr 转写完成后自动发布。可到录音详情检查处理状态。</p><button class="btn" data-sync>${icon('refresh')}立即同步</button></div>`;selectedArchive=item.key;const r=item.r,cached=readerCache.get(item.key);return `<div class="archive-layout"><div class="panel archive-list" aria-label="已归档录音">${files.map(p=>`<button class="archive-item ${p.key===selectedArchive?'active':''}" data-archive="${p.key}" aria-pressed="${p.key===selectedArchive}"><span class="wave-icon">${icon('file')}</span><span><span class="archive-item-title">${esc(p.title)}</span><span class="archive-item-meta" style="display:block">${p.r.time} · ${esc(p.project)}</span><span class="archive-user">${esc(archiveOwner(p))}</span></span></button>`).join('')}</div><article class="panel"><div class="document-head"><span>${icon('file')} 逐字稿预览</span><button class="btn small" data-file="${item.key}/transcript">${icon('download')}下载文本</button></div><div class="document-body"><h2>${esc(item.title)}</h2><div class="document-meta"><span>接入 ${r.date}</span><span>${esc(archiveOwner(item))}</span><span class="num">${duration(item.seconds)}</span><span>${esc(item.project)}</span></div><div id="transcriptReader">${cached?.hash===item.hash?paragraphs(cached.text):'<p class="muted">正在读取演示逐字稿…</p>'}</div><div class="audio-file">${icon('wave')}<div><div>合成测试音频 · AAC</div><div class="muted num">${bytes(r.byteSize)} / 16 kHz / 单声道</div></div><button class="btn small" data-file="${item.key}/audio" style="margin-left:auto">${icon('download')}下载音频</button></div><details><summary>来源与内容校验</summary><dl class="detail-data technical-details"><div><dt>Speakr 录音</dt><dd>${esc(r.speakr_id)}</dd></div><div><dt>上传编号</dt><dd>${esc(r.id)}</dd></div><div><dt>AAC SHA-256</dt><dd>${esc(r.sha256)}</dd></div></dl></details></div></article></div>`;}
function loadReader(){
 const item=publications().find(p=>p.key===selectedArchive);
 if(!item||readerCache.get(item.key)?.hash===item.hash)return;
 const text=transcript(item.key);
 readerCache.set(item.key,{hash:item.hash,text});
 document.getElementById('transcriptReader').innerHTML=paragraphs(text);
}
function connectionsView(){const s=raw.config;return `<div class="form-layout"><div><form id="settingsForm"><section class="panel settings-block"><div class="settings-title">${icon('wave')}<h2>Speakr 录音管理</h2></div><div class="field"><label for="speakrAddress">Speakr 访问地址</label><input id="speakrAddress" name="speakr_url" type="url" value="${esc(s.speakr_url||'')}" placeholder="例如 http://192.168.1.100:8899"><p class="field-hint">仅用于后续转写，不影响 ESP32 接入和原件接收。换地址前，请在录音设备页解除所有人员关联。保存新地址后再重新关联。</p></div></section><section class="panel settings-block"><div class="settings-title">${icon('server')}<h2>推理服务</h2></div><p>转写模型和连接器在 Speakr 中配置。</p><div class="field"><label for="asrAddress">部署备注（不会修改推理配置）</label><input id="asrAddress" name="asr_note" value="${esc(s.asr_note||'')}"></div></section><section class="panel settings-block"><div class="settings-title">${icon('folder')}<h2>文件归档</h2></div><p>按人员自动发布音频和逐字稿，供 Octop 读取。</p><details><summary>查看归档目录与部署说明</summary><div class="field"><label for="archivePath">归档根目录（只读）</label><input id="archivePath" readonly value="${esc(s.archive_path)}"><p class="field-hint">迁移需停机复制整个数据目录并修改 VOXDOCK_DATA，不在工作台直接更换路径。</p></div></details></section><div class="settings-foot"><span class="saved-note">设置仅保留到关闭预览</span><button class="btn primary">${icon('check')}保存连接设置</button></div></form><section class="panel settings-block"><div class="settings-title">${icon('connect')}<h2>关联人员</h2></div><p>选择已经有 Speakr 账号的人员，核实一次授权后即可分配设备。</p><button class="btn" data-associate>关联已有人员</button></section></div><aside class="settings-aside"><h3>接入顺序</h3><p>设备可直接登记并上传原件。需要转写时，填写 Speakr 地址、关联人员，再为设备分配人员。</p><p>VoxDock 负责接收与归档；用户、团队、分享和转写配置继续在 Speakr 管理。</p><section class="verified-users"><h3>已关联人员</h3>${raw.users.map(u=>`<div class="person-summary"><strong>${esc(u.name)}</strong><p class="muted">${esc(groups[u.id])} · 已分配 ${raw.devices.filter(d=>!d.removed_at&&d.user_id===u.id).length} 台设备</p>${u.sync_error?`<p class="reading-error">${esc(advice(u.sync_error))}</p>`:''}${u.upload_error?`<p class="reading-error">${esc(advice(u.upload_error))}</p>`:''}${Math.max(u.retry_after||0,u.upload_retry_after||0)>Date.now()/1000?`<p>下次尝试 ${clock(Math.max(u.retry_after||0,u.upload_retry_after||0))}</p>`:''}</div>`).join('')||'<p>尚未关联人员。</p>'}<button class="link-button" data-navigate="devices">查看人员和设备</button></section></aside></div>`;}
const eventNames={upload_created:'设备开始上传',received:'录音原件已可靠接收',config_saved:'服务配置已保存',device_registered:'录音设备已登记',device_rebound:'设备绑定已修改',device_removed:'设备已移除',person_unlinked:'人员已解除关联',recording_assigned:'录音已分配人员',worker_error:'录音处理失败',sync_error:'归档同步未完成',publication_error:'逐字稿暂不可读取',retry:'重新核实处理状态',retranscribe:'已请求原录音重转写',speakr_accepted:'Speakr 已接收录音',published:'逐字稿已归档',sync_completed:'录音任务已检查'};
function eventsView(){const next={worker_error:'原件仍保留。到录音详情核对错误并恢复处理；权限不足时更新用户 Token。',sync_error:'现有归档保留。检查 Speakr 连接或限流退避时间，恢复后重新同步。',publication_error:'检查逐字稿访问权限和录音状态，恢复后重新同步。'};return `<div class="panel">${state.events.map(e=>{const warn=/error|failed|warn/.test(e.kind),symbol=warn?'alert':e.kind==='upload_created'?'upload':'check',related=state.records.find(r=>e.detail.startsWith(r.id)),relatedDevice=state.devices.find(d=>e.detail===d.id),detail=related?e.detail.replace(related.id,related.title):relatedDevice?relatedDevice.name:e.detail;return `<div class="event-row"><span class="event-time num">${clock(e.created)}</span><span class="event-icon ${warn?'warn':''}">${icon(symbol)}</span><div class="event-body"><strong>${esc(eventNames[e.kind]||e.kind)}</strong><p>${esc(detail)}</p>${warn?`<p class="event-next">${esc(next[e.kind]||'检查运行原因，恢复服务后再次核实。')}</p>${related?`<button class="link-button" data-record="${related.id}">查看录音</button>`:'<button class="link-button" data-navigate="connections">检查服务连接</button>'}`:''}<span class="muted">${date(e.created)}</span></div></div>`;}).join('')||'<div class="empty"><strong>暂无运行记录</strong><p>保存配置、登记设备和接收录音后会记录关键变化。</p></div>'}</div>`;}
function render(){if(!raw)return;uiDirty=false;document.getElementById('breadcrumbCurrent').textContent=titles[page][0];document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const failures=state.records.filter(r=>r.status==='failed').length;document.getElementById('navFailed').textContent=failures;document.getElementById('navFailed').hidden=!failures;document.getElementById('storageCount').textContent=state.records.filter(r=>r.received).length+' 段';document.getElementById('storageCopy').textContent='已接收 '+bytes(raw.uploads.filter(r=>r.received).reduce((s,r)=>s+r.size,0))+' · 磁盘容量未读取';const views={recordings:recordingsView,devices:devicesView,archive:archiveView,connections:connectionsView,events:eventsView};document.getElementById('main').innerHTML=`<div class="page-enter">${head()}${['devices','connections'].includes(page)?setupGuide():''}<div id="updateNotice" class="info-banner" hidden><span>服务器有新的状态，当前阅读和选区已保留。</span><button class="btn small" data-apply-update>更新显示</button></div>${views[page]()}<p class="preview-note">${icon('info')}<span>演示数据 · 操作仅保留到关闭预览</span></p></div>`;if(page==='archive')loadReader();}
function route(){if(location.hash==='#main')return;const id=location.hash.slice(1)||new URLSearchParams(location.search).get('view')||'recordings';page=titles[id]?id:'recordings';filter='all';search='';owner='all';if(raw)render();closeNav(false);}
function navigate(id){if(!titles[id])return;if(location.hash==='#'+id){page=id;if(raw)render();closeNav(false);}else {history.replaceState(null,'','#'+id);route();}document.getElementById('main').focus({preventScroll:true});window.scrollTo(0,0);}
function closeNav(restore=true){const open=document.body.classList.contains('nav-open');document.body.classList.remove('nav-open');document.getElementById('menuButton').setAttribute('aria-expanded','false');if(open&&restore)document.getElementById('menuButton').focus();}
function openNav(){document.body.classList.add('nav-open');document.getElementById('menuButton').setAttribute('aria-expanded','true');document.getElementById('sidebar').focus({preventScroll:true});}
function dialog(title,body){clearTimeout(toastTimer);document.getElementById('toast').classList.remove('show');document.getElementById('dialogTitle').textContent=title;document.getElementById('dialogBody').innerHTML=body;document.getElementById('dialogError').textContent='';document.getElementById('dialog').scrollTop=0;document.getElementById('dialog').showModal();document.getElementById('dialogTitle').focus({preventScroll:true});}
function deviceAddress(){const c=raw.device_connection;return c?.url?`<div class="device-upload-address"><code>${esc(c.url)}</code><button class="btn small" data-copy-address="${esc(c.url)}">${icon('file')}复制地址</button></div><p class="field-hint">自动生成，无需在这里填写。将此地址填到录音设备的“服务器地址”中。</p>`:'<p class="field-hint">暂未识别到设备可用的地址。请用服务器的局域网 IP 打开此页面，再复制自动显示的地址。</p>';}

function copyAddress(button){
 const source=document.createElement('textarea');
 source.value=button.dataset.copyAddress;
 source.readOnly=true;
 source.style.cssText='position:fixed;top:0;left:0;width:1px;height:1px;opacity:0';
 (button.closest('dialog')||document.body).append(source);
 let copied;
 try{source.focus({preventScroll:true});source.select();copied=document.execCommand('copy');}
 finally{source.remove();button.focus({preventScroll:true});}
 if(!copied)throw Error('复制未完成，请选中地址后手动复制。');
 const message='地址已复制，这是演示地址。';
 const feedback=document.getElementById('copyFeedback');
 if(button.closest('dialog'))feedback.textContent=message;
 else toast(message);
}
function deviceCredentials(credential){dialog('设备接入配置',`<p>这是示例接入配置，请勿填入真实设备。</p><h3>录音上传地址</h3>${deviceAddress()}<p id="copyFeedback" class="operation-feedback" role="status"></p><div class="field"><label for="deviceCredential">设备上传凭证（8位数字，仅显示本次）</label><textarea id="deviceCredential" readonly rows="3">${esc(credential)}</textarea></div><p class="field-hint">按原样填写8位数字，保留开头的0，配置一次即可。无需连接 Speakr 即可接收并保存原件。</p><div class="dialog-actions"><button class="btn" data-close="dialog">完成</button></div>`);}
function deviceForm(d={}){return `<form id="deviceForm" data-id="${d.id||''}" data-folder="${d.folder_id||''}" data-tags="${esc(d.tags||'[]')}"><div class="field"><label for="deviceName">设备名称</label><input id="deviceName" name="name" maxlength="100" required value="${esc(d.name||'')}"></div><div class="field"><label for="deviceUser">分配 Speakr 人员（可稍后设置）</label><select id="deviceUser" name="user_id"><option value="">暂不分配，先接收录音</option>${raw.users.map(u=>`<option value="${u.id}" ${u.id===d.user_id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div data-categories aria-live="polite"></div><div class="dialog-actions"><button class="btn primary" id="saveDevice" data-category-save>${d.id?'保存设备设置':'登记设备并生成凭证'}</button><button class="btn" type="button" data-close="dialog">取消</button></div><p class="field-hint">未分配的原件先保留，首次分配后继续转写；已有人员归属的历史录音保持不变。</p></form>`;}

let categoryRequest=0;
async function loadCategories(initial=false){
 const form=document.querySelector('#dialog #deviceForm,#dialog #classificationForm');if(!form)return;
 const box=form.querySelector('[data-categories]'),save=form.querySelector('[data-category-save]'),select=form.querySelector('[name=user_id]'),userId=form.dataset.owner||select.value,request=++categoryRequest;
 const current=()=>request===categoryRequest&&form.isConnected&&document.getElementById('dialog').open&&(form.dataset.owner||form.querySelector('[name=user_id]').value)===userId;
 if(!userId){box.innerHTML='<p class="muted">不连接 Speakr，直接接收并保存录音原件。</p>';save.disabled=Boolean(select?.required);document.getElementById('dialogError').textContent='';return;}
 save.disabled=true;box.textContent='正在读取该人员可用的分类…';document.getElementById('dialogError').textContent='';
 try{const result=await api(`users/${userId}/categories`);if(!current())return;const folders=Array.isArray(result.folders)?result.folders:result.folders.folders,tags=Array.isArray(result.tags)?result.tags:result.tags.tags,selected=initial?JSON.parse(form.dataset.tags):[];
 box.innerHTML=`<div class="field"><label for="folder">${form.id==='classificationForm'?'此录音文件夹':'默认文件夹'}</label><select id="folder" name="folder_id"><option value="">不指定文件夹</option>${folders.map(f=>`<option value="${f.id}" ${initial&&String(f.id)===form.dataset.folder?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><fieldset class="tag-options"><legend>${form.id==='classificationForm'?'此录音标签':'默认标签'}</legend>${tags.map(tag=>`<label><input type="checkbox" name="tag" value="${tag.id}" ${selected.includes(tag.id)?'checked':''}><span>${esc(tag.name)}</span></label>`).join('')||'<p>该人员尚无可用标签。</p>'}</fieldset>`;save.disabled=false;
 }catch(e){if(!current())return;box.innerHTML='<p>无法读取该人员的分类。请检查连接或更新授权，再重新打开表单。</p>';handleError(e);}
}
async function openDevice(id,userId){const d=id?raw.devices.find(d=>d.id===id):{user_id:Number(userId)||null};dialog(id?'修改设备设置':'接入录音设备',deviceForm(d)+(id?`<details><summary>设备凭证与编号</summary><p class="data-id">${esc(id)}</p><button class="btn" data-rotate="${id}">更换设备凭证</button></details>`:''));await loadCategories(true);}

function confirmUnlinkPerson(id,generation){
 const user=raw.users.find(u=>String(u.id)===id);
 if(!user)return;
 dialog('解除人员关联',`<p>确定解除“${esc(user.name)}”的关联吗？</p><p>设备会取消人员和分类绑定，仍可上传原件。已有录音和归档会保留。解除全部人员关联后，可在“服务连接”保存新地址。</p><div class="dialog-actions"><button class="btn" data-close="dialog">取消</button><button class="btn primary" data-confirm-unlink="${user.id}" data-speakr-generation="${generation}">确认解除关联</button></div>`);
}
function confirmRemoveDevice(id){const d=raw.devices.find(d=>d.id===id&&!d.removed_at);if(!d)return;dialog('移除设备',`<p>确定移除“${esc(d.name)}”吗？</p><p>上传凭证将立即失效，设备不能再上传或续传。已接收的录音、转写和归档文件会保留；未完成的录音请保留设备原件。设备需要重新接入时，请重新登记并配置新凭证。</p><div class="dialog-actions"><button class="btn" data-close="dialog">取消</button><button class="btn primary" data-confirm-remove="${d.id}">确认移除</button></div>`);}
async function correctClassification(id){
 const r=state.records.find(r=>r.id===id);
 const assigning=r.user_id==null;
 const title=assigning?'为此录音分配人员':'修正此录音分类';
 const guidance=assigning
  ?'为已保存的这条录音选择 Speakr 人员，保存后会继续转写。'
  :'请选择这条录音的文件夹和标签，保存后可继续投递。';
 const person=assigning
  ?`<div class="field"><label for="recordingUser">Speakr 人员</label><select id="recordingUser" name="user_id" required><option value="">选择已关联人员</option>${raw.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select>${raw.users.length?'':'<p class="field-hint">请先在“服务连接”关联 Speakr 人员。</p>'}</div>`
  :`<p>归属：${esc(r.ownerName)}</p>`;
 document.getElementById('recordDialog').close();
 dialog(title,`<p>录音：${esc(r.title)}</p><p>${guidance}</p><form id="classificationForm" data-id="${r.id}" data-owner="${r.user_id??''}" data-folder="${r.folder_id||''}" data-tags="${esc(r.tags||'[]')}">${person}<div data-categories></div><div class="dialog-actions"><button class="btn primary" data-category-save disabled>${assigning?'保存人员归属':'保存此录音分类'}</button><button class="btn" type="button" data-close="dialog">取消</button></div></form>`);
 if(!assigning)await loadCategories(true);
}
function showRecord(id){const r=state.records.find(r=>r.id===id);if(!r)return;const aborted=r.state==='upload_aborted';const level=aborted||r.state==='uploading'?0:r.state==='validation_failed'?1:r.state==='ready'?4:r.state==='transcribed'?3:r.state==='received'||r.state==='delivery_unknown'?2:2;const steps=[['接收录音',aborted?advice(null,r.state):r.received?`${bytes(r.byteSize)}，完整录音已保存`:`文件上传 ${r.progress}%，${bytes(r.offset)} 已确认`],['校验文件',r.aac_check?'文件长度、SHA-256 与 ADTS 结构已检查':r.state==='validation_failed'?advice(r.error,r.state,r.delivery_outcome):'完整接收后校验长度、SHA-256 与 ADTS 结构'],['Speakr 转写',aborted?'等待接收完整录音':r.speakrPaused?(r.historical?'此录音保留在原连接下':'人员已解除关联，暂停处理'):r.user_id==null?(device(r.device).removed_at?'原件已保留，可为此录音分配 Speakr 人员':'原件保留，等待为设备分配 Speakr 人员'):r.speakr_id?statusNames[r.state]:r.delivery_outcome==='rejected'?'Speakr 明确拒绝；修复权限或限流后可重试，没有先前未知投递。':r.state==='delivery_unknown'?'投递结果不明，核实引用后关联已有录音':'尚未确认 Speakr 已接收'],['发布归档',r.state==='ready'?'音频与逐字稿已写入用户目录':advice(raw.users.find(u=>!r.speakrPaused&&u.id===r.user_id)?.sync_error)||'完成后可供 Octop 读取']];document.getElementById('recordDetails').innerHTML=`<h3 class="drawer-title">${esc(r.title)}</h3><div class="drawer-meta">${r.date} ${r.time} · ${esc(r.project)}</div><div class="drawer-wave" aria-hidden="true" title="录音标记，非声波分析">${Array.from({length:42},(_,i)=>`<i style="height:${8+Math.abs(Math.sin(i*1.7)*Math.cos(i*.3))*48}px"></i>`).join('')}</div><div>${stateLabel(r)}</div>${raw.users.find(u=>!r.speakrPaused&&u.id===r.user_id)?.sync_error?`<div class="detail-error">最近同步未完成：${esc(advice(raw.users.find(u=>u.id===r.user_id).sync_error))}。${r.state==='ready'?'现有归档仍然可读。':'请在运行记录中查看原因。'}</div>`:''}<h4 class="drawer-section-title">处理进度</h4><ol class="steps">${steps.map(([title,description],i)=>{const isError=aborted?i===0:(r.state==='validation_failed'&&i===1)||(failed(r)&&r.state!=='validation_failed'&&i===2),done=i<level;return `<li class="step ${isError?'error':i<=level?'':'pending'}"><span class="step-icon">${icon(isError?'alert':done?'check':i===level?'clock':'right')}</span><div><strong>${title}</strong><p>${esc(description)}</p></div></li>`;}).join('')}</ol>${r.error&&!aborted?`<div class="detail-error">${esc(advice(r.error,r.state,r.delivery_outcome))}<br>${r.received?'原始录音已保留，无需设备重新上传。':'请保留设备原件，核对校验结果后恢复上传。'}</div>`:''}${!r.speakrPaused&&(r.user_id!=null||device(r.device).removed_at)&&!r.speakr_id&&r.state==='received'&&['rejected','unattempted'].includes(r.delivery_outcome)?`<button class="btn" data-correct="${r.id}">${r.user_id==null?'为此录音分配人员':'修正此录音分类'}</button>`:''}<h4 class="drawer-section-title">录音信息</h4><dl class="detail-data"><div><dt>来源设备</dt><dd>${esc(device(r.device).name)}</dd></div><div><dt>所属用户</dt><dd>${esc(r.ownerName)}</dd></div><div><dt>录音时长</dt><dd>${duration(r.seconds)}</dd></div><div><dt>音频格式</dt><dd>AAC-LC / 16 kHz / 单声道</dd></div></dl><details><summary>技术详情与来源</summary><dl class="detail-data technical-details">${Object.entries({'上传编号':r.id,'设备录音编号':r.recording_id,'Speakr 录音 ID':r.speakr_id||'尚未确认','接收字节':`${r.offset} / ${r.byteSize} B`,'SHA-256':r.sha256,'音频检查':r.aac_check||'尚未完成','投递事实':r.delivery_outcome||'旧记录待核实','技术错误':r.error||'无'}).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${r.received?`<button class="btn" data-file="${r.user_id||0}/${r.id}/audio">下载原件</button>`:''}</details>${!r.speakrPaused&&r.state==='delivery_unknown'?`<section class="manual-link"><h4 class="drawer-section-title">核实已有录音</h4><p>先到 Speakr 核对外部引用，再填写已有录音编号。此操作不会新建录音。</p><form id="linkForm" data-id="${r.id}"><div class="field"><label for="remoteId">经 Speakr 核实的已有录音 ID</label><input id="remoteId" type="number" min="1" required></div><div class="dialog-actions"><button class="btn">核实引用并关联</button></div></form></section>`:''}<p id="recordFeedback" class="operation-feedback" role="status"></p><p id="recordError" class="field-error" role="alert"></p>`;document.getElementById('recordActions').innerHTML=`<button class="btn" data-close="recordDialog">关闭详情</button>${r.state==='ready'?`<button class="btn primary" data-read="${r.id}">${icon('file')}查看逐字稿</button>`:r.speakrPaused?'':r.state==='transcription_failed'?`<button class="btn primary" data-action="retranscribe" data-id="${r.id}">${icon('refresh')}重转写原录音</button>`:r.user_id!=null&&r.received&&r.state!=='deleted'?`<button class="btn primary" data-action="retry" data-id="${r.id}">${icon('refresh')}${!r.speakr_id&&['rejected','unattempted'].includes(r.delivery_outcome)?'投递此录音':'核实此录音'}</button>`:''}`;document.getElementById('recordDetails').scrollTop=0;document.getElementById('recordDialog').showModal();document.getElementById('recordDialogTitle').focus({preventScroll:true});}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b)return;try{
 if(b.hasAttribute('data-sample-access')){b.nextElementSibling.hidden=false;b.nextElementSibling.focus();}
 else if(b.classList.contains('skip-link')){event.preventDefault();document.getElementById('main').focus({preventScroll:false});}
 else if(b.dataset.page){event.preventDefault();navigate(b.dataset.page);}else if(b.dataset.navigate)navigate(b.dataset.navigate);
 else if(b.dataset.close)document.getElementById(b.dataset.close).close();
 else if(b.hasAttribute('data-go-login')){document.getElementById('dialog').close();document.getElementById('main').focus();}
 else if(b.dataset.action==='account')account();else if(b.hasAttribute('data-change-password'))passwordForm();
 else if(b.hasAttribute('data-logout')){await api('logout',{method:'POST'},true);clearSession('已退出登录。');}
 else if(b.hasAttribute('data-associate'))associate(b.dataset.associate);
 else if(b.dataset.assign)await openDevice(null,b.dataset.assign);
 else if(b.dataset.record||b.dataset.detail)showRecord(b.dataset.record||b.dataset.detail);
 else if(b.dataset.correct)await correctClassification(b.dataset.correct);
 else if(b.dataset.unlinkPerson)confirmUnlinkPerson(b.dataset.unlinkPerson,b.dataset.speakrGeneration);
 else if(b.dataset.confirmUnlink){
  b.disabled=true;
  try{
   await api('users/'+b.dataset.confirmUnlink+'?generation='+b.dataset.speakrGeneration,{method:'DELETE'});
   document.getElementById('dialog').close();
   if(await reload())toast('已解除关联，原有录音和归档已保留。');
  }finally{b.disabled=false;}
 }
 else if(b.dataset.removeDevice)confirmRemoveDevice(b.dataset.removeDevice);
 else if(b.dataset.confirmRemove){b.disabled=true;try{await api('devices/'+b.dataset.confirmRemove,{method:'DELETE'});document.getElementById('dialog').close();if(await reload())toast('设备已移除，历史录音已保留。');}finally{b.disabled=false;}}
 else if(b.dataset.editDevice)await openDevice(b.dataset.editDevice);
 else if(b.dataset.filter){filter=b.dataset.filter;render();document.querySelector(`[data-filter="${filter}"]`).focus();}
 else if(b.dataset.archive){selectedArchive=b.dataset.archive;render();document.querySelector(`[data-archive="${selectedArchive}"]`).focus();}
 else if(b.dataset.read){selectedArchive=publications().find(p=>p.r.id===b.dataset.read)?.key||'';document.getElementById('recordDialog').close();navigate('archive');}
 else if(b.dataset.action==='add-device')await openDevice();
 else if(b.dataset.action==='clear-filter'){filter='all';search='';owner='all';render();}
 else if(b.hasAttribute('data-apply-update')){render();document.getElementById('main').focus({preventScroll:true});}
 else if(b.dataset.action==='archive-help')dialog('归档文件',`<p>音频和逐字稿按人员授权自动归档。普通使用无需手工拼接目录。</p><details><summary>技术接线与目录</summary><p class="data-id">${esc(raw.config.archive_path)}</p><p>Octop 只读挂载对应人员的 archive 子目录，不挂载含授权信息的 state。</p></details><div class="dialog-actions"><button class="btn" data-sync>检查全部录音任务</button></div>`);
 else if(b.dataset.action==='about'){closeNav(false);dialog('本地实例',`<p>本实例接收原件、校验文件，再交给 Speakr 转写。接收完成后，设备无需因转写失败重新上传。</p><p>人员和设备分配在工作台仅保留到关闭预览。归档按 Speakr 的可访问权限更新。</p><p id="refreshFeedback" class="operation-feedback" role="status"></p><div class="dialog-actions"><button class="btn" data-refresh>刷新状态</button><button class="btn" data-action="account">管理员账号</button></div>`);}
 else if(b.hasAttribute('data-refresh')){const prior=document.getElementById('refreshFeedback');if(prior)prior.textContent='';b.disabled=true;const ok=await reload();if(ok){const feedback=document.getElementById('refreshFeedback');if(feedback)feedback.textContent='已刷新演示状态。';else toast('已刷新演示状态。');}b.disabled=false;}
 else if(b.hasAttribute('data-copy-address'))copyAddress(b);
 else if(b.hasAttribute('data-sync')){b.disabled=true;await api('sync',{method:'POST'});if(await reload())toast('已检查全部录音任务，具体结果请查看状态与运行记录。');b.disabled=false;}
 else if(b.hasAttribute('data-reader-retry'))await loadReader();
 else if(b.dataset.rotate){const c=await api(`devices/${b.dataset.rotate}/rotate`,{method:'POST'});deviceCredentials(c.credential);}
 else if(['retry','retranscribe'].includes(b.dataset.action)){b.disabled=true;const result=await api(`uploads/${b.dataset.id}/${b.dataset.action}`,{method:'POST'});if(await reload()){showRecord(b.dataset.id);const feedback=document.getElementById('recordFeedback'),status=result.action_result;feedback.textContent=(status?.message||'已请求本条录音重新转写。')+(status?.next_attempt_at?` 下次尝试：${clock(status.next_attempt_at)}`:'');feedback.scrollIntoView({block:'nearest'});}b.disabled=false;}
 else if(b.dataset.file){
  const audio=b.dataset.file.endsWith('/audio');
  const url=audio?'./meeting.aac':URL.createObjectURL(new Blob([transcript(b.dataset.file)],{type:'text/markdown;charset=utf-8'}));
  const link=document.createElement('a');link.href=url;link.download=b.dataset.file.split('/')[1]+(audio?'-演示.aac':'-演示.md');link.click();
  if(!audio)setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
 }catch(e){b.disabled=false;handleError(e);}});
document.addEventListener('submit',async event=>{event.preventDefault();const f=event.target,buttons=[...f.querySelectorAll('button[type=submit],button:not([type])')];buttons.forEach(b=>b.disabled=true);try{
 if(f.id==='login'){session=await api('login',{method:'POST',body:JSON.stringify({username:document.getElementById('username').value,password:document.getElementById('password').value})},true);authGeneration++;await reload();return;}
 if(f.id==='passwordForm'){const next=document.getElementById('newPassword').value;if(next!==document.getElementById('confirmPassword').value)throw Error('两次新密码不一致，请重新输入。');session=await api('password',{method:'POST',body:JSON.stringify({current_password:document.getElementById('currentPassword').value,new_password:next})},true);authGeneration++;await reload();dialog('密码已更新','<p>本次演示仍保持登录。若退出，请使用刚设置的新密码。</p><div class="dialog-actions"><button class="btn" data-close="dialog">完成</button></div>');return;}
 if(f.id==='associateForm'){const token=f.querySelector('#userToken').value,targetId=f.dataset.userId?Number(f.dataset.userId):null,payload={token,...(targetId?{expected_user_id:targetId}:{})};if(f.verifiedToken===token){await api('users',{method:'POST',body:JSON.stringify(payload)});f.verifiedToken=null;document.getElementById('dialog').close();if(await reload()){navigate('devices');toast(targetId?'该人员授权已更新。':'人员已关联，现在可以为他分配设备。');}return;}const sequence=(f.verifySequence||0)+1;f.verifySequence=sequence;const identity=await api('users/verify',{method:'POST',body:JSON.stringify(payload)});if(!f.isConnected||!document.getElementById('dialog').open||f.verifySequence!==sequence||f.querySelector('#userToken').value!==token)return;f.verifiedToken=token;f.querySelector('#personPreview').innerHTML=`<div class="identity-preview"><strong>${esc(identity.name)}</strong><p>连接和身份核实成功。请确认这是要关联的人员。</p><p class="muted">${identity.group_memberships.map(g=>esc(g.group_name)).join('、')||'未加入团队'}</p></div>`;f.querySelector('#verifyPerson').textContent=targetId?'确认更新授权':'确认关联';return;}
 if(f.id==='settingsForm'){const d=Object.fromEntries(new FormData(f));await api('config',{method:'PUT',body:JSON.stringify(d)});}
 else if(f.id==='deviceForm'){const d=Object.fromEntries(new FormData(f));d.user_id=d.user_id?Number(d.user_id):null;d.folder_id=d.folder_id?Number(d.folder_id):null;d.tags=[...f.querySelectorAll('[name=tag]:checked')].map(x=>Number(x.value));delete d.tag;const result=await api('devices'+(f.dataset.id?'/'+f.dataset.id:''),{method:f.dataset.id?'PUT':'POST',body:JSON.stringify(d)});document.getElementById('dialog').close();if(await reload()){if(result.credential)deviceCredentials(result.credential);else toast('设备设置已保存。');}return;}
 else if(f.id==='classificationForm'){const d=new FormData(f),userId=d.get('user_id');await api(`uploads/${f.dataset.id}/classification`,{method:'PUT',body:JSON.stringify({...(userId?{user_id:Number(userId)}:{}),folder_id:d.get('folder_id')?Number(d.get('folder_id')):null,tags:[...f.querySelectorAll('[name=tag]:checked')].map(x=>Number(x.value))})});document.getElementById('dialog').close();if(await reload()){showRecord(f.dataset.id);document.getElementById('recordFeedback').textContent=userId?'人员已分配，录音将继续转写。':'此录音分类已修正。点击“投递此录音”继续，无需设备重传。';}return;}
 else if(f.id==='linkForm'){await api(`uploads/${f.dataset.id}/link`,{method:'POST',body:JSON.stringify({speakr_id:Number(document.getElementById('remoteId').value)})});document.getElementById('recordDialog').close();}
 if(await reload())toast('已保存到本次演示。');
 }catch(e){if(f.id==='login')error(e.message);else handleError(e);}finally{if(f.isConnected)buttons.forEach(b=>b.disabled=false);}});
document.addEventListener('input',event=>{if(event.target.id==='userToken'){const form=event.target.form;form.verifiedToken=null;form.verifySequence=(form.verifySequence||0)+1;form.querySelector('#personPreview').textContent='';form.querySelector('#verifyPerson').textContent='核实姓名';}if(event.target.id==='recordSearch'){search=event.target.value;document.getElementById('recordRows').innerHTML=tableRows();document.getElementById('recordCount').textContent=`共 ${visibleRecords().length} 段录音`;}});
document.addEventListener('change',event=>{if(['deviceUser','recordingUser'].includes(event.target.id))loadCategories();if(event.target.id==='ownerFilter'){owner=event.target.value;document.getElementById('recordRows').innerHTML=tableRows();document.getElementById('recordCount').textContent=`共 ${visibleRecords().length} 段录音`;}});
const close=document.createElement('button');close.id='sidebarClose';close.className='icon-btn sidebar-close';close.setAttribute('aria-label','关闭导航');close.innerHTML=icon('close');document.getElementById('sidebar').prepend(close);
close.addEventListener('click',()=>closeNav());document.getElementById('mobileOverlay').addEventListener('click',()=>closeNav());
document.getElementById('menuButton').addEventListener('click',()=>document.body.classList.contains('nav-open')?closeNav():openNav());
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.querySelector('dialog[open]')){if(document.body.classList.contains('nav-open')){event.preventDefault();closeNav();}else if(parent!==window){event.preventDefault();parent.postMessage({type:'case-demo-close'},location.origin);}}if(event.key==='Tab'&&document.body.classList.contains('nav-open')){const targets=[...document.getElementById('sidebar').querySelectorAll('a,button')];const first=targets[0],last=targets[targets.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===document.getElementById('sidebar'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',route);
document.getElementById('currentDate').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Shanghai'});
route();
restoreSession().then(()=>{if(raw&&parent!==window)parent.postMessage({type:'case-demo-ready'},location.origin);});
})();
